import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"roadmap.md","filePath":"roadmap.md","lastUpdated":1793733635000}'),d={name:"roadmap.md"};function i(s,e,n,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h1><p>Ordered by the tie-breakers in <code>SOUL.md</code>: the user&#39;s safety and agency first, protocol conformance second, the applet developer&#39;s ability to build third. Nothing here is dated. An item moves off this page when its scenarios pass and its docs exist.</p><h2 id="_1-upstream-pull-requests-to-kehto" tabindex="-1">1. Upstream pull requests to kehto <a class="header-anchor" href="#_1-upstream-pull-requests-to-kehto" aria-label="Permalink to &quot;1. Upstream pull requests to kehto&quot;">​</a></h2><p>None is filed yet. Each item shrinks kernl when it lands; see <a href="./alpha-status#upstream-gaps">Alpha status</a>.</p><ul><li>Forward <code>getFocusContext</code>, <code>onFirewallEvent</code> and <code>firewallPersistence</code> through <code>ShellAdapter</code> so the runtime&#39;s own firewall can be focus-aware without a second engine in front of it.</li><li>Let the host choose the ACL default policy in <code>createRuntime</code>, so a restrictive shell does not have to write every capability explicitly.</li><li>Offer a hook that can hold or drop port traffic, so the visibility gate can hold a hidden applet&#39;s envelopes instead of only observing them before dispatch.</li><li>Release <code>experimental.nestedContextLock</code> in <code>@kehto/shell</code>, so kernl can pass the flag to <code>prepareNappletSrcdoc</code> and delete its port of the lock (<a href="./decisions#d-014">D-014</a>).</li><li>Let the runtime firewall measure envelopes without an <code>event</code>, so its size matchers see downloads and queries and kernl can drop <code>refuseCurrentDispatch</code> (<a href="./decisions#d-012">D-012</a>).</li><li>Expose a setter for the runtime firewall&#39;s <code>unfocusedMultiplier</code>. Together with the forwarded <code>getFocusContext</code>, it lets the runtime refuse an unfocused window at the profile&#39;s tightened budget instead of treating every window as focused.</li></ul><h2 id="_2-bridge-backends" tabindex="-1">2. Bridge backends <a class="header-anchor" href="#_2-bridge-backends" aria-label="Permalink to &quot;2. Bridge backends&quot;">​</a></h2><p>Each backend plugs into the path the HTTP bridge already exercises end to end. Order reflects how much of the user&#39;s exposure each one changes; see <a href="./concepts/bridges">Bridges</a>.</p><table tabindex="0"><thead><tr><th>Backend</th><th>Interface</th><th>Notes</th></tr></thead><tbody><tr><td>Mail</td><td><code>MailBackend</code></td><td>Opens or creates a conversation for a <code>mailto:</code> locator. Candidate for a shell-side IMAP/JMAP client or a hand-off to a configured mail account.</td></tr><tr><td>NZB</td><td><code>NzbBackend</code></td><td>Hands an <code>nzb:</code> locator to a configured downloader. The downloader runs outside the browser; the bridge reports job state.</td></tr><tr><td>Torrent</td><td><code>TorrentBackend</code></td><td>Adds an info hash with its trackers. WebTorrent in the shell, or a configured external client. Marked as public activity in the exposure description.</td></tr><tr><td>Soulseek</td><td><code>SoulseekBackend</code></td><td>Requests one file from one peer. Requires a daemon; the bridge reports job state.</td></tr></tbody></table><p>The shell also needs a downloads view that shows the state of each <code>job</code> result and lets the user cancel it; there is none today.</p><h2 id="_3-messaging" tabindex="-1">3. Messaging <a class="header-anchor" href="#_3-messaging" aria-label="Permalink to &quot;3. Messaging&quot;">​</a></h2><ul><li>Supply the double-ratchet runtime so the <code>ratchet</code> provider reports <code>available</code>. Its properties are already described; see <a href="./concepts/messaging">Messaging</a>.</li><li>Per-conversation provider migration: move a correspondent from <code>legacy</code> to <code>private</code> when both clients can read it, shown as a reversible choice.</li></ul><h2 id="_4-mobile-layouts" tabindex="-1">4. Mobile layouts <a class="header-anchor" href="#_4-mobile-layouts" aria-label="Permalink to &quot;4. Mobile layouts&quot;">​</a></h2><p>The window manager contracts come from <code>@kehto/wm</code>. A narrow-viewport layout with a window switcher, gestures for focus and dismissal, and the same visibility semantics the guard relies on (a window off screen is hidden, and hidden windows are deferred).</p><h2 id="_5-account-switching" tabindex="-1">5. Account switching <a class="header-anchor" href="#_5-account-switching" aria-label="Permalink to &quot;5. Account switching&quot;">​</a></h2><p><code>AccountManager</code> already holds several accounts. The missing piece is a switcher that makes the active account visible on every screen, keeps grants scoped to the account that gave them, and never signs a write with an account the user did not pick for that window.</p><h2 id="_6-guard" tabindex="-1">6. Guard <a class="header-anchor" href="#_6-guard" aria-label="Permalink to &quot;6. Guard&quot;">​</a></h2><ul><li>Per-applet guard profiles: today the profile is shell-wide and resets to <code>strict</code> on boot (<a href="./decisions#d-003">D-003</a>). Next: an override per applet identity, remembered locally.</li><li>Re-narrow a live applet&#39;s advertised environment when a domain is revoked; today the ACL denies at once but <code>shell.init</code> only changes on the next open.</li><li>Bridge consent per host: wire <code>createDefaultBridges({ authorize })</code> to a host prompt so a granted <code>resource</code> request still asks before reaching a new origin.</li><li>Persist per-applet profile overrides and grants through a user-chosen sync, so loosening an applet once does not have to be repeated per device.</li></ul><h2 id="_7-conformance" tabindex="-1">7. Conformance <a class="header-anchor" href="#_7-conformance" aria-label="Permalink to &quot;7. Conformance&quot;">​</a></h2><ul><li>Run <code>@napplet/conformance</code> against the shell&#39;s bridge in <code>pnpm test</code>: envelope validators per NAP domain, manifest validation and the reference mock shell&#39;s expectations of a host. Today conformance is checked by the <code>features/</code> scenarios and review only (<a href="./policies/spec-conformance">Spec conformance</a>).</li></ul><h2 id="not-planned" tabindex="-1">Not planned <a class="header-anchor" href="#not-planned" aria-label="Permalink to &quot;Not planned&quot;">​</a></h2><ul><li>A global configuration flag that loosens a mitigation for every applet. <code>SOUL.md</code> opinion three rules it out.</li><li>A second event library beside applesauce. <code>DECISIONS.md</code> <a href="./decisions#d-002">D-002</a> rules it out.</li><li>A &quot;recommended&quot; messaging provider. <a href="./decisions#d-009">D-009</a> rules it out.</li></ul>',21)])])}const f=t(d,[["render",i]]);export{u as __pageData,f as default};
